            })

            -- User Avatar
            local UserAvatar = New("ImageLabel", {
                BackgroundColor3 = Library.Scheme.AccentColor,
                Image = WindowInfo.UserPanelIcon or "rbxassetid://97682394690683",
                Size = UDim2.fromOffset(50, 50),
