            MinimizeButton.MouseButton1Click:Connect(function()
                Library.Window:SetMinimized(true)
            end)

            --// The minimized card: a header with the icon, title and subtitle, an
            --// optional body of labels, and the window footer along the bottom.
            MiniFrame = New("Frame", {
                AutomaticSize = Enum.AutomaticSize.Y,
                BackgroundColor3 = function()
                    return Library:GetBetterColor(Library.Scheme.BackgroundColor, -1)
                end,
                Name = "Minimized",
                Position = WindowInfo.Position,
                Size = UDim2.fromOffset(WindowInfo.MinimizedWidth, 0),
                Visible = false,
                Parent = ScreenGui,
            })
            table.insert(
                Library.Corners,
                New("UICorner", {
                    CornerRadius = UDim.new(0, WindowInfo.CornerRadius),
                    Parent = MiniFrame,
                })
            )
            table.insert(
                Library.Scales,
                New("UIScale", {
                    Parent = MiniFrame,
                })
            )
            Library:AddOutline(MiniFrame)

            New("UIListLayout", {
                FillDirection = Enum.FillDirection.Vertical,
                SortOrder = Enum.SortOrder.LayoutOrder,
                Parent = MiniFrame,
            })

            --// Header \\--
            local MiniHeader = New("Frame", {
                BackgroundTransparency = 1,
                LayoutOrder = 0,
                Size = UDim2.new(1, 0, 0, 46),
                Parent = MiniFrame,
            })
            New("UIPadding", {
                PaddingLeft = UDim.new(0, 12),
                PaddingRight = UDim.new(0, 10),
                Parent = MiniHeader,
            })
            New("UIListLayout", {
                FillDirection = Enum.FillDirection.Horizontal,
