            local RestoreIcon = Library:GetIcon("chevron-up")
            local RestoreButton = New("TextButton", {
                BackgroundTransparency = 1,
                LayoutOrder = 2,
                Size = UDim2.fromOffset(22, 22),
                Text = RestoreIcon and "" or "^",
